create or replace function public.create_project_state_action_command(project_state_input uuid,title_input text,due_date_input date default null,lifecycle_stage_input text default null,capability_key_input text default null) returns void language plpgsql set search_path to '' as $$ begin perform private.assert_cross_stage_project_state_writable(project_state_input); if nullif(btrim(title_input),'') is null then raise exception 'Action title is required'; end if; if lifecycle_stage_input is not null and lifecycle_stage_input not in ('opportunity','qualification','predevelopment','authorization') then raise exception 'Invalid lifecycle stage'; end if; insert into public.actions(project_state_id,title,due_date,status,created_by,lifecycle_stage,capability_key) values(project_state_input,btrim(title_input),due_date_input,'open',auth.uid(),lifecycle_stage_input,nullif(btrim(capability_key_input),'')); end $$;
create or replace function public.create_project_state_risk_issue_command(project_state_input uuid,kind_input text,title_input text,severity_input text default null,lifecycle_stage_input text default null,capability_key_input text default null) returns void language plpgsql set search_path to '' as $$ begin perform private.assert_cross_stage_project_state_writable(project_state_input); if nullif(btrim(title_input),'') is null then raise exception 'Risk/issue title is required'; end if; if lifecycle_stage_input is not null and lifecycle_stage_input not in ('opportunity','qualification','predevelopment','authorization') then raise exception 'Invalid lifecycle stage'; end if; insert into public.risk_issues(project_state_id,kind,title,severity,status,created_by,lifecycle_stage,capability_key) values(project_state_input,coalesce(nullif(btrim(kind_input),''),'risk'),btrim(title_input),nullif(btrim(severity_input),''),'open',auth.uid(),lifecycle_stage_input,nullif(btrim(capability_key_input),'')); end $$;
create or replace function public.record_project_state_decision_command(project_state_input uuid,decision_type_input text,outcome_input text,rationale_input text default null,authority_basis_input text default null,lifecycle_stage_input text default null,capability_key_input text default null) returns void language plpgsql set search_path to '' as $$ begin perform private.assert_cross_stage_project_state_writable(project_state_input); if nullif(btrim(decision_type_input),'') is null or nullif(btrim(outcome_input),'') is null then raise exception 'Decision type and outcome are required'; end if; if lifecycle_stage_input is not null and lifecycle_stage_input not in ('opportunity','qualification','predevelopment','authorization') then raise exception 'Invalid lifecycle stage'; end if; insert into public.decisions(project_state_id,decision_type,outcome,rationale,authority_basis,actor_user_id,lifecycle_stage,capability_key) values(project_state_input,btrim(decision_type_input),btrim(outcome_input),nullif(btrim(rationale_input),''),nullif(btrim(authority_basis_input),''),auth.uid(),lifecycle_stage_input,nullif(btrim(capability_key_input),'')); end $$;
create or replace function public.create_project_state_evidence_command(project_state_input uuid,title_input text,source_system_input text,source_url_input text,provenance_note_input text,knowledge_state_input public.knowledge_state,lifecycle_stage_input text default null,capability_key_input text default null) returns void language plpgsql set search_path to '' as $$ begin perform private.assert_cross_stage_project_state_writable(project_state_input); if nullif(btrim(title_input),'') is null then raise exception 'Evidence title is required'; end if; if lifecycle_stage_input is not null and lifecycle_stage_input not in ('opportunity','qualification','predevelopment','authorization') then raise exception 'Invalid lifecycle stage'; end if; insert into public.evidence_references(project_state_id,title,source_system,source_url,provenance_note,knowledge_state,created_by,lifecycle_stage,capability_key) values(project_state_input,btrim(title_input),coalesce(nullif(btrim(source_system_input),''),'google_drive'),nullif(btrim(source_url_input),''),nullif(btrim(provenance_note_input),''),knowledge_state_input,auth.uid(),lifecycle_stage_input,nullif(btrim(capability_key_input),'')); end $$;
revoke all on function public.create_project_state_action_command(uuid,text,date,text,text) from public,anon; revoke all on function public.create_project_state_risk_issue_command(uuid,text,text,text,text,text) from public,anon; revoke all on function public.record_project_state_decision_command(uuid,text,text,text,text,text,text) from public,anon; revoke all on function public.create_project_state_evidence_command(uuid,text,text,text,text,public.knowledge_state,text,text) from public,anon;
grant execute on function public.create_project_state_action_command(uuid,text,date,text,text) to authenticated; grant execute on function public.create_project_state_risk_issue_command(uuid,text,text,text,text,text) to authenticated; grant execute on function public.record_project_state_decision_command(uuid,text,text,text,text,text,text) to authenticated; grant execute on function public.create_project_state_evidence_command(uuid,text,text,text,text,public.knowledge_state,text,text) to authenticated;
